# -*- coding: utf-8 -*-
from pathlib import Path
content = """@import \"tailwindcss\";\n\n/* ========================================\n  ?é® AIROUTE Í∏ÄÎ°úÎ≤å ?§Ì???n  ?§ÌÅ¨ ?åÎßà Í∏∞Î∞ò - Tailwind ?¥Îûò???∞ÏÑ†\n  ======================================== */\n\n::root {\n  color-scheme: dark;\n  --bg: #020617;\n  --bg-gradient: radial-gradient(circle at 15% 20%, rgba(59, 130, 246, 0.25), transparent 45%),\n    radial-gradient(circle at 80% 5%, rgba(99, 102, 241, 0.25), transparent 40%),\n    linear-gradient(180deg, rgba(2, 6, 23, 0.95) 0%, rgba(2, 8, 36, 0.92) 55%, #01030d 100%);\n  --text-strong: #f5f7ff;\n  --text: #dbe4ff;\n  --text-muted: #94a3b8;\n  --card-bg: rgba(8, 12, 28, 0.85);\n  --card-border: rgba(255, 255, 255, 0.08);\n  --card-shadow: 0 25px 60px rgba(2, 6, 23, 0.85);\n  --background: var(--bg);\n  --foreground: var(--text);\n}\n\n@theme inline {\n  --color-background: var(--background);\n  --color-foreground: var(--foreground);\n  --font-sans: var(--font-inter);\n}\n\n/* ========================================\n  ?ìè Í∏∞Î≥∏ Î¶¨ÏÖã\n  ======================================== */\n\nhtml,\nbody {\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background-color: var(--bg);\n  background-image: var(--bg-gradient);\n  background-repeat: no-repeat;\n  background-attachment: fixed;\n  color: var(--text);\n  min-height: 100vh;\n  font-family: var(--font-sans), system-ui, -apple-system, BlinkMacSystemFont, sans-serif;\n}\n\nbody,\nmain,\nsection,\narticle,\nbutton,\ninput,\ntextarea,\nselect {\n  color: var(--text);\n}\n\na {\n  text-decoration: none;\n  color: inherit;\n}\n\n/* ========================================\n  ?ìù ?Ä?¥Ìè¨Í∑∏Îûò??- font-weight ?§Ï†ï\n  ======================================== */\n\nh1, h2, h3, h4, h5, h6 {\n  font-weight: 700;\n  color: var(--text-strong);\n}\n\nstrong, b {\n  font-weight: 600;\n  color: var(--text-strong);\n}\n\n.card-standard {\n  background: var(--card-bg);\n  border: 1px solid var(--card-border);\n  box-shadow: var(--card-shadow);\n  border-radius: 1rem;\n  backdrop-filter: blur(18px);\n}\n\n/* ========================================\n  ?îÑ ?§ÌÅ¨Î°§Î∞î ?§Ì??ºÎßÅ (?§ÌÅ¨ ?åÎßà)\n  ======================================== */\n\n:::-webkit-scrollbar {\n  width: 8px;\n  height: 8px;\n}\n\n:::-webkit-scrollbar-track {\n  background: rgb(15 23 42); /* slate-900 */\n}\n\n:::-webkit-scrollbar-thumb {\n  background: rgb(51 65 85); /* slate-700 */\n  border-radius: 4px;\n}\n\n:::-webkit-scrollbar-thumb:hover {\n  background: rgb(71 85 105); /* slate-600 */\n}\n\n/* Í∞ÄÎ°??§ÌÅ¨Î°??ÅÏó≠ ?§ÌÅ¨Î°§Î∞î ?®Í∏∞Í∏?*/\n.no-scrollbar,\n.scrollbar-hide {\n  -ms-overflow-style: none;\n  scrollbar-width: none;\n}\n\n.no-scrollbar::-webkit-scrollbar,\n.scrollbar-hide::-webkit-scrollbar {\n  display: none;\n}\n"""
Path('src/app/globals.css').write_text(content, encoding='utf-8')
